/// Run the js-bench-editor/Blockbench topological loop walk from the selected edge.
/// Rendering remains triangle soup, but adjacency and traversal use stable vertex ids;
/// a boundary, non-quad, or closed ring terminates the walk instead of changing the
/// operation into an infinite plane slice.
pub fn meshTopoLoopCut() bool {
    if (!model_paint.hasTarget()) return false;
    const edge_idx = mesh_edit.selectedEdgeIndexPub() orelse return false;
    const ep = mesh_edit.edgeEndpointsPub(edge_idx);
    const a = mesh_edit.vertPosPub(ep[0]);
    const b = mesh_edit.vertPosPub(ep[1]);
    const selected_part = mesh_edit.selectedEdgePartPub();
    if (z3d.vdot(z3d.vsub(b, a), z3d.vsub(b, a)) < 1e-12) return false;

    const verts = z3d.g_edit_verts orelse return false;
    const tri_count = z3d.g_edit_count / 3;
    if (tri_count == 0) return false;
    const base_colors = z3d.collectCurrentFaceColors() orelse return false;
    defer std.heap.c_allocator.free(base_colors);

    // Per-tri authored group (null when this mesh has no grouping — plain imports).
    var groups_buf: ?[]u32 = null;
    defer if (groups_buf) |g| std.heap.c_allocator.free(g);
    if (model_source.faceGroupOf(0) != model_source.NO_FACE_GROUP) {
        const g = std.heap.c_allocator.alloc(u32, tri_count) catch return false;
        var i: u32 = 0;
        while (i < tri_count) : (i += 1) g[i] = model_source.faceGroupOf(i);
        groups_buf = g;
    }

    // Per-face part parentage BEFORE the cut, so the fresh group ids the cut mints can
    // renormalize back into their parts' contiguous ranges after install (req_2644).
    const base_part = z3d.capturePartOfFaces();
    defer if (base_part) |bp| std.heap.c_allocator.free(bp);
    const part_count = z3d.hostPartCount();

    const groups_arg: ?[]const u32 = if (groups_buf) |g| g else null;
    const parts_arg: ?[]const u32 = if (base_part) |p| p else null;
    var indexed = z3d.cloneIndexedEditMeshOrImport(verts, tri_count, groups_arg, parts_arg, model_source.faceMaterials()) orelse return false;
    defer indexed.deinit();
    if (!(indexed.loopCutFromEdge(a, b, selected_part, 1, 0.5) catch return false)) return false;
    var cut = indexed.lower() catch return false;
    defer cut.deinit();
    if (cut.tri_count <= tri_count) return false;
    const cut_colors = std.heap.c_allocator.alloc(u8, @as(usize, cut.tri_count) * 4) catch return false;
    defer std.heap.c_allocator.free(cut_colors);
    if (!mesh_edit.inheritFaceRgba(base_colors, cut.source_triangles, cut_colors)) return false;

    var snap = z3d.journalSnapshotCurrent("loop cut");
    const install_groups: ?[]const u32 = if (groups_arg != null) cut.groups else null;
    const ok = z3d.lcInstallLowered(cut.positions, cut.uvs, cut.tri_count, install_groups, cut.materials, cut.semantic_regions, cut.semantic_instances, cut_colors, z3d.flattenedLogicalRows(cut.triangle_vertices), @intCast(indexed.vertices.items.len));
    if (ok) {
        if (base_part) |bp| {
            _ = bp;
            z3d.renormalizePartRanges(cut.parts, part_count);
        }
        z3d.adoptIndexedEditMesh(&indexed, &cut);
        mesh_edit.setMode(.edge);
        z3d.journalCommit(&snap);
    } else z3d.journalDiscard(&snap);
    return ok;
}

/// Split the one authored face shared by exactly two selected, non-adjacent
/// welded vertices. The new diagonal becomes the selected editable edge.
pub fn meshTopoConnectVertices() bool {
    if (z3d.g_lc != null or z3d.g_bevel != null or z3d.g_quadify != null or !model_paint.hasTarget()) return false;
    var selected: [2]u32 = undefined;
    if (mesh_edit.selectedVerticesPub(selected[0..]) != 2) return false;
    const a = mesh_edit.vertPosPub(selected[0]);
    const b = mesh_edit.vertPosPub(selected[1]);
    const verts = z3d.g_edit_verts orelse return false;
    const tri_count = z3d.g_edit_count / 3;
    if (tri_count == 0) return false;
    const base_colors = z3d.collectCurrentFaceColors() orelse return false;
    defer std.heap.c_allocator.free(base_colors);
    const groups = z3d.captureFaceGroups();
    defer if (groups) |rows| std.heap.c_allocator.free(rows);
    const parts = z3d.capturePartOfFaces();
    defer if (parts) |rows| std.heap.c_allocator.free(rows);
    const groups_arg: ?[]const u32 = if (groups) |rows| rows else null;
    const parts_arg: ?[]const u32 = if (parts) |rows| rows else null;
    var indexed = z3d.cloneIndexedEditMeshOrImport(verts, tri_count, groups_arg, parts_arg, model_source.faceMaterials()) orelse return false;
    defer indexed.deinit();
    if (!(indexed.connectVertices(selected[0], selected[1]) catch return false)) return false;
    // Mirror (req_3797): connect every twin pair too — one connect per enabled plane
    // subset, all in the same commit. A twin pair that exists but cannot connect
    // refuses the whole op (never commit a half-symmetric connect).
    if (mesh_edit.mirrorMask() != 0) {
        var done: [7][2]u32 = undefined;
        var done_count: usize = 0;
        done[0] = .{ @min(selected[0], selected[1]), @max(selected[0], selected[1]) };
        done_count = 1;
        var subset: u8 = 1;
        while (subset <= 7) : (subset += 1) {
            const t0 = mesh_edit.mirrorTwinOfVertPub(selected[0], subset) orelse continue;
            const t1 = mesh_edit.mirrorTwinOfVertPub(selected[1], subset) orelse continue;
            const pair = [2]u32{ @min(t0, t1), @max(t0, t1) };
            var seen = false;
            for (done[0..done_count]) |have| {
                if (have[0] == pair[0] and have[1] == pair[1]) seen = true;
            }
            if (seen) continue;
            done[done_count] = pair;
            done_count += 1;
            if (!(indexed.connectVertices(t0, t1) catch return false)) return false;
        }
    }
    var lowered = indexed.lower() catch return false;
    defer lowered.deinit();
    const colors = std.heap.c_allocator.alloc(u8, @as(usize, lowered.tri_count) * 4) catch return false;
    defer std.heap.c_allocator.free(colors);
    if (!mesh_edit.inheritFaceRgba(base_colors, lowered.source_triangles, colors)) return false;

    var snap = z3d.journalSnapshotCurrent("connect vertices");
    const install_groups: ?[]const u32 = if (groups_arg != null) lowered.groups else null;
    const ok = z3d.lcInstallLowered(lowered.positions, lowered.uvs, lowered.tri_count, install_groups, lowered.materials, lowered.semantic_regions, lowered.semantic_instances, colors, z3d.flattenedLogicalRows(lowered.triangle_vertices), @intCast(indexed.vertices.items.len));
    if (!ok) {
        z3d.journalDiscard(&snap);
        return false;
    }
    if (parts != null) z3d.renormalizePartRanges(lowered.parts, z3d.hostPartCount());
    z3d.adoptIndexedEditMesh(&indexed, &lowered);
    _ = z3d.selectWeldedEdgeAt(a, b);
    mesh_edit.setMode(.edge);
    z3d.journalCommit(&snap);
    return true;
}

// ── Symmetrize + symmetry check (the studio's req_1190/1191/1192, host-native — req_2831) ──
// The trust layer the mirror planes shipped without: a live "is it symmetric?" count and
// the keep+/− repair. Both use the same identity domains and the same fixed plane as live
// mirrored transforms: mesh_edit.MIRROR_PLANE_CENTER, the model origin. Never a bounds
// midpoint — a derived plane moved with every one-sided edit and cut where the user never
// asked (req_3795). Scope is authoritative: focused parts are repaired, and every other
// part passes through untouched.

/// Returns {plane center, unmatched, total} for logical vertices in the current
/// outliner scope. Pairing prefers a vertex's own part and falls back to any part,
/// exactly like live mirrored transforms.
pub fn meshSymmetryReport(axis: u8) ?[3]f32 {
    if (axis > 2 or !model_paint.hasTarget()) return null;
    return mesh_edit.symmetryReportPub(axis);
}

/// One-shot part symmetrize derives its plane from the focused part's bounds at
/// invocation; quantizing the midpoint keeps repeated repairs on the same plane
/// even as micro-asymmetries move the raw bounds by float dust.
pub const SYMMETRIZE_PART_PLANE_QUANTUM_M: f32 = 0.0001;

/// Port of Studio symmetrize (req_1190): repair the active outliner part(s), not the
/// composed model. WHOLE-MODEL scope cuts at the shared model-origin plane — the
/// same plane Mirror Part duplicates across, so "center, then mirror" is the whole
/// workflow (req_1538). A FOCUSED part instead symmetrizes about its OWN centerline
/// (req_3886): a detached head rest repairs in place rather than reflecting across
/// the entire model. The one-shot verb may derive that plane at invocation; armed
/// mirror-edit twinning keeps the fixed origin authority, because planes re-derived
/// across EDITS are what drifted (req_3795). Selection clears, as in the original UI.
pub fn meshTopoSymmetrize(axis: u8, keep_positive: bool) bool {
    if (axis > 2 or !model_paint.hasTarget()) return false;
    const original_mode = mesh_edit.mode();
    const verts = z3d.g_edit_verts orelse return false;
    const tri_count = z3d.g_edit_count / 3;
    if (tri_count == 0) return false;
    const base_colors = z3d.collectCurrentFaceColors() orelse return false;
    defer std.heap.c_allocator.free(base_colors);
    const groups = z3d.captureFaceGroups();
    defer if (groups) |rows| std.heap.c_allocator.free(rows);
    const parts = z3d.capturePartOfFaces();
    defer if (parts) |rows| std.heap.c_allocator.free(rows);
    const part_count = z3d.hostPartCount();
    const groups_arg: ?[]const u32 = if (model_source.faceGroupOf(0) != model_source.NO_FACE_GROUP) groups else null;
    var indexed = z3d.cloneIndexedEditMeshOrImport(verts, tri_count, groups_arg, parts, model_source.faceMaterials()) orelse return false;
    defer indexed.deinit();
    if (parts) |face_parts| {
        if (part_count == 0) return false;
        const target_parts = std.heap.c_allocator.alloc(bool, @intCast(part_count)) catch return false;
        defer std.heap.c_allocator.free(target_parts);
        @memset(target_parts, false);
        var in_scope: u32 = 0;
        var face: u32 = 0;
        while (face < tri_count) : (face += 1) {
            if (!mesh_edit.faceInScopePub(face)) continue;
            in_scope += 1;
            const part = face_parts[@intCast(face)];
            const part_index: usize = @intCast(part);
            if (part_index < target_parts.len) target_parts[part_index] = true;
        }
        const centers = std.heap.c_allocator.alloc(f32, @intCast(part_count)) catch return false;
        defer std.heap.c_allocator.free(centers);
        for (centers) |*center| center.* = mesh_edit.MIRROR_PLANE_CENTER[axis];
        if (in_scope < tri_count) {
            // Focused scope (req_3886): each targeted part repairs about its own
            // quantized bounds midpoint on the chosen axis, measured right now.
            const lo = std.heap.c_allocator.alloc(f32, @intCast(part_count)) catch return false;
            defer std.heap.c_allocator.free(lo);
            const hi = std.heap.c_allocator.alloc(f32, @intCast(part_count)) catch return false;
            defer std.heap.c_allocator.free(hi);
            @memset(lo, std.math.floatMax(f32));
            @memset(hi, -std.math.floatMax(f32));
            face = 0;
            while (face < tri_count) : (face += 1) {
                const part_index: usize = @intCast(face_parts[@intCast(face)]);
                if (part_index >= target_parts.len or !target_parts[part_index]) continue;
                var corner: u32 = 0;
                while (corner < 3) : (corner += 1) {
                    const value = verts[(@as(usize, face) * 3 + corner) * 8 + axis];
                    lo[part_index] = @min(lo[part_index], value);
                    hi[part_index] = @max(hi[part_index], value);
                }
            }
            for (centers, 0..) |*center, part_index| {
                if (!target_parts[part_index] or lo[part_index] > hi[part_index]) continue;
                const midpoint = (lo[part_index] + hi[part_index]) * 0.5;
                center.* = @round(midpoint / z3d.SYMMETRIZE_PART_PLANE_QUANTUM_M) * z3d.SYMMETRIZE_PART_PLANE_QUANTUM_M;
            }
        }
        if (!(indexed.symmetrizePartsAt(axis, centers, keep_positive, target_parts) catch return false)) return false;
    } else {
        if (!(indexed.symmetrize(axis, mesh_edit.MIRROR_PLANE_CENTER[axis], keep_positive) catch return false)) return false;
    }
    var lowered = indexed.lower() catch return false;
    defer lowered.deinit();
    if (lowered.tri_count == 0) return false;
    const colors = std.heap.c_allocator.alloc(u8, @as(usize, lowered.tri_count) * 4) catch return false;
    defer std.heap.c_allocator.free(colors);
    if (!mesh_edit.inheritFaceRgba(base_colors, lowered.source_triangles, colors)) return false;

    var snap = z3d.journalSnapshotCurrent("symmetrize");
    const install_groups: ?[]const u32 = if (groups_arg != null) lowered.groups else null;
    const ok = z3d.lcInstallLowered(lowered.positions, lowered.uvs, lowered.tri_count, install_groups, lowered.materials, lowered.semantic_regions, lowered.semantic_instances, colors, z3d.flattenedLogicalRows(lowered.triangle_vertices), @intCast(indexed.vertices.items.len));
    if (ok) {
        if (parts != null) z3d.renormalizePartRanges(lowered.parts, part_count);
        z3d.adoptIndexedEditMesh(&indexed, &lowered);
        // The shared indexed-lowering install deliberately enters face mode.
        // Studio symmetrize instead preserves the active tool and clears its selection.
        mesh_edit.setMode(original_mode);
        mesh_edit.clearSelection();
        z3d.journalCommit(&snap);
    } else z3d.journalDiscard(&snap);
    return ok;
}

// ── Loop cut on a FACE: reference topological walk in a host-owned session ────
// Direction selects an ordered edge of the clicked face. The cut follows opposite
// edges by stable vertex identity, terminates at boundaries/non-quads, and previews
// live from a captured indexed base. Journal commit happens only on end(commit);
// cancel restores the base exactly and leaves no undo entry.
pub const LcSession = struct {
    basic: bool,
    base_mesh: indexed_edit_mesh.Mesh,
    last_mesh: ?indexed_edit_mesh.Mesh,
    base_paint_layout_stale: bool,
    base_groups: ?[]u32, // per-tri authored groups at begin (null = ungrouped import)
    base_colors: []u8, // true RGBA per base face; previews inherit through src_face
    // Authored faces cut by this session. Loop Cut keeps the exact selection; Basic
    // Cut adds in-scope mirror twins after the clicked face has supplied the seed.
    base_cut_mask: []bool,
    // Part parentage (req_2644): one part index per BASE face at begin, and the same
    // carried through the LAST installed preview — commit renormalizes the minted
    // group ids back into contiguous per-part ranges from this.
    base_face_part: ?[]u32,
    last_face_part: ?[]u32, // per LAST-preview face; aliases nothing (owned)
    part_count: u32,
    // The seed face's first two ordered edge directions. Propagated loop cut still
    // receives the clicked face's edge index; bounded Basic Cut passes the chosen
    // world vector through so every selected face resolves the same orientation.
    dirs: [2][3]f32,
    lo: [2]f32, // selected-face extent along each cut direction (dot-space)
    hi: [2]f32,
    keep_group: u32, // clicked face's group id — its −side piece re-selects after commit
    keep_face_id: u32, // stable indexed face id of the retained −side piece
    snap: ?z3d.JournalEntry,
    // Overlay visibility (req_2625): the selection's world centroid at begin anchors
    // the handle; last_planes is a visual guide, not the cutting algorithm.
    sel_center: [3]f32 = .{ 0, 0, 0 },
    last_dir: u32 = 0,
    last_planes: [64]f32 = undefined,
    last_plane_count: u32 = 0,
    // Full last-preview params (req_2625 gap DD): the handle drag re-previews at the
    // session's own dir/cuts, and __mesh_lc_state echoes them back to the popup.
    last_cuts: u32 = 1,
    last_offset_frac: f32 = 0.5,
    // The handle drag's CONTINUOUS cursor offset (req_2644 QQ): previews install the
    // SNAPPED frac, so the raw position accumulates here or slow drags could never
    // cross a whole-unit detent. Every preview re-seeds it (steppers move both).
    drag_raw_frac: f32 = 0.5,
    // Apply is legal only after the CURRENT params installed an actual preview. A
    // failed preview used to fall through meshLoopCutFaceEnd(commit), renumber the
    // untouched model, and reselect by group as though a cut had happened.
    last_preview_ok: bool = false,
    last_reason: ?[]const u8 = null,
};

/// One size-unit in world space — the mesh basis (16 u = 1 tile), the loop-cut handle's
/// default snap increment (req_2644 QQ) and the studio gizmo's own step law.
pub const LC_SNAP_WORLD: f32 = 1.0 / 16.0;

pub fn lcFree() void {
    var s = z3d.g_lc orelse return;
    s.base_mesh.deinit();
    if (s.last_mesh) |*mesh| mesh.deinit();
    if (s.base_groups) |g| std.heap.c_allocator.free(g);
    std.heap.c_allocator.free(s.base_colors);
    std.heap.c_allocator.free(s.base_cut_mask);
    if (s.base_face_part) |p| std.heap.c_allocator.free(p);
    if (s.last_face_part) |p| std.heap.c_allocator.free(p);
    z3d.journalDiscard(&s.snap);
    z3d.g_lc = null;
}

/// Dominant world axis of a direction (largest |component|) — the gizmo color /
/// fallback-axis rule shared by the loop-cut handle and direction derivation.
pub fn domAxis(v: [3]f32) u8 {
    const x = @abs(v[0]);
    const y = @abs(v[1]);
    const z = @abs(v[2]);
    return if (x >= y and x >= z) 0 else if (y >= z) 1 else 2;
}

/// The plane comb for `cuts` planes at `offset` within [lo,hi] — the studio's
/// loopCutPositions: at offset = size/2 the planes divide the span into cuts+1 EQUAL
/// slabs; raising the offset translates the comb toward +axis, shrinking the −side
/// (selected-face) end slab. Planes that land outside the span are skipped.
pub fn lcPlanes(lo: f32, hi: f32, cuts: u32, offset: f32, out: []f32) u32 {
    const n: u32 = @max(1, cuts);
    const size = hi - lo;
    const even = size / @as(f32, @floatFromInt(n + 1));
    const shift = -(offset - size / 2.0);
    var m: u32 = 0;
    var k: u32 = 1;
    while (k <= n and m < out.len) : (k += 1) {
        const p = lo + @as(f32, @floatFromInt(k)) * even + shift;
        if (p > lo + 1e-5 and p < hi - 1e-5) {
            out[m] = p;
            m += 1;
        }
    }
    return m;
}

/// Derive the render soup from indexed positions + per-corner UVs and install it
/// without repacking the live paint atlas. Normals are derived here; topology and UV
/// identity remain owned by indexed_edit_mesh. Stays in face mode.
pub fn lcInstallLowered(
    pos: []const f32,
    uvs: []const f32,
    tri_count: u32,
    groups: ?[]const u32,
    materials: []const u32,
    semantic_regions: []const u32,
    semantic_instances: []const u32,
    colors: []const u8,
    logical_rows: []const u32,
    logical_vertex_count: u32,
) bool {
    if (pos.len != @as(usize, tri_count) * 9 or
        uvs.len != @as(usize, tri_count) * 6 or
        colors.len != @as(usize, tri_count) * 4 or
        materials.len != tri_count or
        semantic_regions.len != tri_count or
        semantic_instances.len != tri_count or
        logical_rows.len != @as(usize, tri_count) * 3 or
        logical_vertex_count == 0) return false;
    var out: std.ArrayListUnmanaged(f32) = .empty;
    var t: u32 = 0;
    while (t < tri_count) : (t += 1) {
        const b = @as(usize, t) * 9;
        const uv = @as(usize, t) * 6;
        const p0: [3]f32 = .{ pos[b + 0], pos[b + 1], pos[b + 2] };
        const p1: [3]f32 = .{ pos[b + 3], pos[b + 4], pos[b + 5] };
        const p2: [3]f32 = .{ pos[b + 6], pos[b + 7], pos[b + 8] };
        const tri_uvs = [3][2]f32{
            .{ uvs[uv + 0], uvs[uv + 1] },
            .{ uvs[uv + 2], uvs[uv + 3] },
            .{ uvs[uv + 4], uvs[uv + 5] },
        };
        if (!z3d.appendTriWithUvs(&out, p0, p1, p2, tri_uvs)) {
            out.deinit(std.heap.c_allocator);
            return false;
        }
    }
    const owned = out.toOwnedSlice(std.heap.c_allocator) catch {
        out.deinit(std.heap.c_allocator);
        return false;
    };
    defer std.heap.c_allocator.free(owned);
    // Modeling precedes Paint. Before the user creates/imports an authored atlas,
    // topology installs through the ordinary geometry path and derives any internal
    // preview layout afresh. Only real authored pixels license the preservation path.
    const preserve_authored_atlas = model_paint.hasAuthoredAtlas();
    const installed = if (preserve_authored_atlas)
        z3d.replaceActiveEditMeshPreservingAtlas(owned, tri_count * 3, groups, colors, .{ .exact = .{
            .rows = logical_rows,
            .vertex_count = logical_vertex_count,
        } })
    else
        z3d.replaceActiveEditMesh(owned, tri_count * 3, .{ .exact = .{
            .rows = logical_rows,
            .vertex_count = logical_vertex_count,
        } });
    if (!installed) return false;
    if (!preserve_authored_atlas) {
        // There are no authored pixels whose coordinates can be stale yet.
        z3d.g_paint_layout_stale = false;
        if (groups) |rows| model_source.setFaceGroups(rows);
        if (!z3d.applyExactFaceColors(colors, tri_count)) return false;
        if (groups != null) _ = z3d.refreshPaintLayout();
    }
    model_source.setFaceMaterials(materials);
    if (!model_source.setFaceSemantics(semantic_regions, semantic_instances)) return false;
    mesh_edit.setMode(.face);
    return true;
}

pub const LcInfo = struct { size0: f32, size1: f32 };

/// Open a loop-cut session on the CURRENT face selection: capture the indexed base and
/// expose the first face's first two ordered edge lengths as direction choices. Returns
/// those two lengths for the popup, or null when not in face mode /
/// nothing selected. A prior session (stale popup) is dropped, not committed.
pub fn meshLoopCutFaceBegin(basic: bool) ?z3d.LcInfo {
    z3d.g_topo_refusal = "";
    if (z3d.g_bevel != null) {
        z3d.topoRefuse("a bevel session is still open — close or cancel it first");
        return null;
    }
    z3d.lcFree();
    if (!model_paint.hasTarget()) {
        z3d.topoRefuse("no paint target is bound to this model");
        return null;
    }
    if (mesh_edit.mode() != .face) {
        z3d.topoRefuse("loop cut needs FACE select mode");
        return null;
    }
    const verts = z3d.g_edit_verts orelse {
        z3d.topoRefuse("no editable mesh is resident");
        return null;
    };
    const tri_count = z3d.g_edit_count / 3;
    if (tri_count == 0) {
        z3d.topoRefuse("the mesh has no triangles");
        return null;
    }
    // The mask is sized by the MESH, never by the paint layout (req_4114). It used to be
    // a paint-layout array guarded by `model_paint.faceCount() < tri_count`, which refused
    // the whole operation whenever the atlas was stale, degenerate, or simply absent —
    // i.e. exactly while a model is being edited, which is the only time anyone cuts. The
    // extra headroom keeps buildDeleteMask's own `out.len >= paint faceCount` contract.
    const mask = std.heap.c_allocator.alloc(bool, @max(tri_count, model_paint.faceCount())) catch {
        z3d.topoRefuse("out of memory building the selection mask");
        return null;
    };
    defer std.heap.c_allocator.free(mask);
    @memset(mask, false);
    if (mesh_edit.buildDeleteMask(mask) == 0) {
        z3d.topoRefuse("no faces are selected");
        return null;
    }
    // Selection sets can outlive a scope change. The topology session starts from the
    // intersection, never from stale selected faces in sibling outliner parts.
    var selected_in_scope: u32 = 0;
    var scoped_face: u32 = 0;
    while (scoped_face < tri_count) : (scoped_face += 1) {
        mask[scoped_face] = mask[scoped_face] and mesh_edit.faceInScopePub(scoped_face);
        if (mask[scoped_face]) selected_in_scope += 1;
    }
    if (selected_in_scope == 0) {
        z3d.topoRefuse("every selected face is outside the focused part's scope");
        return null;
    }

    var groups: ?[]u32 = null;
    if (model_source.faceGroupOf(0) != model_source.NO_FACE_GROUP) {
        const g = std.heap.c_allocator.alloc(u32, tri_count) catch return null;
        var i: u32 = 0;
        while (i < tri_count) : (i += 1) g[i] = model_source.faceGroupOf(i);
        groups = g;
    }

    const base_cut_mask = std.heap.c_allocator.dupe(bool, mask[0..tri_count]) catch {
        if (groups) |g| std.heap.c_allocator.free(g);
        return null;
    };
    const base_colors = z3d.collectCurrentFaceColors() orelse {
        if (groups) |g| std.heap.c_allocator.free(g);
        std.heap.c_allocator.free(base_cut_mask);
        return null;
    };
    if (base_colors.len != @as(usize, tri_count) * 4) {
        z3d.topoRefuse("per-face colour capture disagreed with the mesh triangle count");
        if (groups) |g| std.heap.c_allocator.free(g);
        std.heap.c_allocator.free(base_cut_mask);
        std.heap.c_allocator.free(base_colors);
        return null;
    }

    const base_face_part = z3d.capturePartOfFaces();
    const groups_arg: ?[]const u32 = if (groups) |g| g else null;
    const parts_arg: ?[]const u32 = if (base_face_part) |p| p else null;
    var base_mesh = z3d.cloneIndexedEditMeshOrImport(verts, tri_count, groups_arg, parts_arg, model_source.faceMaterials()) orelse {
        if (groups) |g| std.heap.c_allocator.free(g);
        std.heap.c_allocator.free(base_cut_mask);
        std.heap.c_allocator.free(base_colors);
        if (base_face_part) |p| std.heap.c_allocator.free(p);
        return null;
    };
    const seed = base_mesh.seedInfo(base_cut_mask) orelse {
        z3d.topoRefuse("the selected faces give no cuttable seed face (need an authored quad/n-gon, not a lone or degenerate triangle)");
        base_mesh.deinit();
        if (groups) |g| std.heap.c_allocator.free(g);
        std.heap.c_allocator.free(base_cut_mask);
        std.heap.c_allocator.free(base_colors);
        if (base_face_part) |p| std.heap.c_allocator.free(p);
        return null;
    };
    // The user's face owns popup direction, phase, and retained selection even when
    // its mirror twin has an earlier triangle id. Expand only the operation mask,
    // after capturing that seed, so Basic Cut joins the other bilateral topology
    // verbs without changing bounded-cut reach into loop propagation.
    if (basic and mesh_edit.mirrorMask() != 0) {
        z3d.extendFaceMaskWithMirrorTwins(verts, tri_count, base_cut_mask);
    }

    z3d.g_lc = .{
        .basic = basic,
        .base_mesh = base_mesh,
        .last_mesh = null,
        .base_paint_layout_stale = z3d.g_paint_layout_stale,
        .base_groups = groups,
        .base_colors = base_colors,
        .base_cut_mask = base_cut_mask,
        .base_face_part = base_face_part,
        .last_face_part = null, // no preview yet — commit falls back to the base parts
        .part_count = z3d.hostPartCount(),
        .dirs = seed.directions,
        .lo = seed.lo,
        .hi = seed.hi,
        .keep_group = seed.keep_group,
        .keep_face_id = seed.face_id,
        .snap = z3d.journalSnapshotCurrent(if (basic) "cut" else "loop cut"),
        .sel_center = seed.center,
    };
    return .{ .size0 = seed.sizes[0], .size1 = seed.sizes[1] };
}

/// Re-run the reference topological edit from the captured indexed base and lower
/// the result for rendering. No plane fallback exists: traversal termination is a
/// successful partial ring, exactly as in js-bench-editor.
pub fn meshLoopCutFacePreview(dir: u32, cuts: u32, offset_frac: f32) bool {
    const s: *z3d.LcSession = if (z3d.g_lc) |*sp| sp else return false;
    s.last_preview_ok = false;
    s.last_reason = if (s.basic)
        "Cut preview could not be built"
    else
        "Loop-cut preview could not be built";
    const d: usize = @min(dir, 1);
    const cut_count = @min(@max(cuts, 1), 64);
    const reuse_topology = s.last_mesh != null and s.last_dir == @as(u32, @intCast(d)) and s.last_cuts == cut_count;

    // Keep the popup overlay/read-back contract. These planes are display guides only;
    // topology is determined exclusively by the indexed edge walk below.
    var planes: [64]f32 = undefined;
    const span = s.hi[d] - s.lo[d];
    if (span < 1e-6) {
        s.last_reason = "Selected face has no usable cut span";
        return false;
    }
    // A cut at the exact span end mints vertices ON existing corners: invisible in
    // the preview, but the next soup→indexed weld collapses them into degenerate
    // faces (req_3435 — how the record player's spindle got poisoned). Keep the
    // fraction far enough inside the span that no seed-edge cut can land within
    // the weld tolerance; the walk-output check below backstops shorter edges.
    const weld_guard = @min(0.45, (indexed_edit_mesh.IMPORT_WELD_EPS * 2.0) / span);
    const fraction = std.math.clamp(offset_frac, weld_guard, 1.0 - weld_guard);
    const n_planes = z3d.lcPlanes(s.lo[d], s.hi[d], cut_count, fraction * span, &planes);
    s.last_dir = @intCast(d);
    s.last_planes = planes;
    s.last_plane_count = n_planes;
    s.last_cuts = cut_count;
    s.last_offset_frac = fraction;
    s.drag_raw_frac = fraction;

    var preview = if (reuse_topology)
        s.last_mesh.?.clone() catch return false
    else
        s.base_mesh.clone() catch return false;
    defer preview.deinit();
    const changed = if (reuse_topology) blk: {
        preview.repositionCutVertices(cut_count, fraction, if (s.basic) s.dirs[d] else null);
        break :blk true;
    } else if (s.basic)
        preview.cutSelected(s.base_cut_mask, s.dirs[d], cut_count, fraction) catch return false
    else
        preview.loopCut(s.base_cut_mask, @intCast(d), cut_count, fraction) catch return false;
    if (!changed) {
        s.last_reason = if (s.basic)
            "This authored face cannot be split by the selected cut"
        else
            "No quad or triangle loop crosses this authored face — split the n-gon into quads first";
        return false;
    }
    // Backstop for edges shorter than the seed span (thin bands): if ANY minted
    // cut vertex sits within the weld tolerance of its edge's end, this preview
    // would not survive its own save/load — refuse it instead of poisoning the doc.
    if (preview.degenerateCutVertexCount() > 0) {
        s.last_reason = "Cut lands on an existing edge or corner — change the offset";
        return false;
    }

    var lowered = preview.lower() catch return false;
    defer lowered.deinit();
    const colors = std.heap.c_allocator.alloc(u8, @as(usize, lowered.tri_count) * 4) catch return false;
    defer std.heap.c_allocator.free(colors);
    if (!mesh_edit.inheritFaceRgba(s.base_colors, lowered.source_triangles, colors)) return false;

    if (s.last_face_part) |p| std.heap.c_allocator.free(p);
    s.last_face_part = null;
    if (s.base_face_part != null) {
        s.last_face_part = std.heap.c_allocator.dupe(u32, lowered.parts) catch return false;
    }
    const install_groups: ?[]const u32 = if (s.base_groups != null) lowered.groups else null;
    if (!z3d.lcInstallLowered(lowered.positions, lowered.uvs, lowered.tri_count, install_groups, lowered.materials, lowered.semantic_regions, lowered.semantic_instances, colors, z3d.flattenedLogicalRows(lowered.triangle_vertices), @intCast(preview.vertices.items.len))) return false;
    // The cut mints fresh authored groups above the document's existing ids. Until
    // commit those ids still need to belong to the source Outliner part; otherwise
    // face/edge overlays obey the old range and show only the retained first strip.
    if (s.last_face_part) |face_part| z3d.renormalizePartRanges(face_part, s.part_count);
    if (s.last_mesh) |*mesh| mesh.deinit();
    s.last_mesh = preview;
    preview = .{ .allocator = std.heap.c_allocator };
    s.last_preview_ok = true;
    s.last_reason = null;
    return true;
}

/// Close the session. commit keeps the previewed cut as ONE journal entry and re-selects
/// the clicked face's retained piece (the indexed split keeps its original group id,
/// so the selection rides the cut like the studio's, req_0989). cancel restores the
/// captured base exactly and leaves no undo entry.
pub fn meshLoopCutFaceEnd(commit: bool) bool {
    const active: *const z3d.LcSession = if (z3d.g_lc) |*session| session else return false;
    // No preview was ever installed: closing a refused n-gon cut is literally inert.
    // Do not re-key the mesh or mark the document dirty just for dismissing the popup.
    if (!active.last_preview_ok and active.last_mesh == null) {
        z3d.lcFree();
        return false;
    }
    var s = z3d.g_lc orelse return false;
    var ok = true;
    // Applying a semantic no-op is a cancel, not a topology transaction. Restore the
    // captured base because a failed parameter change may follow an earlier successful
    // preview that is still resident on screen.
    if (commit and s.last_preview_ok) {
        z3d.journalCommit(&s.snap);
        // Renormalize the minted +side group ids back into their parts' contiguous
        // ranges (req_2644). The stable indexed face id, not a pre-normalization group
        // number, identifies the retained −side piece for re-selection.
        const fp: ?[]const u32 = if (s.last_face_part) |p| p else if (s.base_face_part) |p| p else null;
        var keep_face: ?u32 = null;
        if (s.last_mesh) |*mesh| {
            if (mesh.lower()) |lowered_value| {
                var lowered = lowered_value;
                defer lowered.deinit();
                for (lowered.face_ids, 0..) |face_id, triangle| {
                    if (face_id == s.keep_face_id) {
                        keep_face = @intCast(triangle);
                        break;
                    }
                }
            } else |_| {}
        }
        if (fp) |face_part| z3d.renormalizePartRanges(face_part, s.part_count);
        if (s.last_mesh) |*mesh| {
            if (mesh.lower()) |lowered_value| {
                var lowered = lowered_value;
                defer lowered.deinit();
                z3d.adoptIndexedEditMesh(mesh, &lowered);
            } else |_| {}
        }
        if (keep_face) |f| {
            const g = model_source.faceGroupOf(f);
            if (g != model_source.NO_FACE_GROUP) _ = mesh_edit.selectFacesByGroupRange(g, g + 1, false);
        } else if (s.keep_group != model_source.NO_FACE_GROUP) {
            _ = mesh_edit.selectFacesByGroupRange(s.keep_group, s.keep_group + 1, false);
        }
        mesh_edit.setMode(.face);
    } else {
        const groups_arg: ?[]const u32 = if (s.base_groups) |g| g else null;
        if (s.base_mesh.lower()) |lowered_value| {
            var lowered = lowered_value;
            defer lowered.deinit();
            ok = z3d.lcInstallLowered(lowered.positions, lowered.uvs, lowered.tri_count, groups_arg, lowered.materials, lowered.semantic_regions, lowered.semantic_instances, s.base_colors, z3d.flattenedLogicalRows(lowered.triangle_vertices), @intCast(s.base_mesh.vertices.items.len));
        } else |_| {
            ok = false;
        }
        if (ok) {
            if (s.base_face_part) |face_part| z3d.renormalizePartRanges(face_part, s.part_count);
            if (s.base_mesh.clone()) |restored_value| {
                var restored = restored_value;
                defer restored.deinit();
                if (restored.lower()) |lowered_value| {
                    var lowered = lowered_value;
                    defer lowered.deinit();
                    z3d.adoptIndexedEditMesh(&restored, &lowered);
                } else |_| {}
            } else |_| {}
            z3d.g_paint_layout_stale = s.base_paint_layout_stale;
        }
        z3d.journalDiscard(&s.snap);
    }
    s.base_mesh.deinit();
    if (s.last_mesh) |*mesh| mesh.deinit();
    if (s.base_groups) |g| std.heap.c_allocator.free(g);
    std.heap.c_allocator.free(s.base_colors);
    if (s.base_face_part) |p| std.heap.c_allocator.free(p);
    if (s.last_face_part) |p| std.heap.c_allocator.free(p);
    z3d.journalDiscard(&s.snap); // no-op when committed
    z3d.g_lc = null;
    return ok;
}

/// A host-captured topology popup session is LIVE. The engine's press routing treats
/// it as MODAL: loop cut exposes its drawn handle; bevel consumes viewport presses so
/// nothing can mutate the selection either session's captured base was built from.
/// Popup buttons and Esc are the exits.
pub fn meshLcActive() bool {
    return z3d.g_lc != null or z3d.g_bevel != null or z3d.g_quadify != null;
}

pub const LcState = struct {
    dir: u32,
    world_direction: [3]f32,
    cuts: u32,
    offset_frac: f32,
    fallback_reason: ?[]const u8,
};
/// The live session's last-previewed params — the __mesh_lc_state read-back. A host-side
/// handle drag re-previews internally, so the popup polls this to keep its steppers and
/// offset cell tracking the drag.
pub fn meshLcState() ?z3d.LcState {
    const sp: *const z3d.LcSession = if (z3d.g_lc) |*p| p else return null;
    return .{
        .dir = sp.last_dir,
        .world_direction = sp.dirs[@min(sp.last_dir, 1)],
        .cuts = sp.last_cuts,
        .offset_frac = sp.last_offset_frac,
        .fallback_reason = sp.last_reason,
    };
}

pub fn meshLcFallbackReason() ?[]const u8 {
    const sp: *const z3d.LcSession = if (z3d.g_lc) |*p| p else return null;
    return sp.last_reason;
}

// ── Marquee-projected cut (req_4271) ─────────────────────────────────────────────
// Ctrl+drag a screen rectangle over a face: the four marquee edges project through
// the camera onto the face as four cut lines (screen rect → corner rays → planes →
// intersect the face), the face splits along every line that crosses it, and the
// cells inside the rectangle come back SELECTED — the desktop-icon sweep, as a cut.

/// The plane through the camera eye containing the rays of two viewport points,
/// oriented so the marquee interior (probed by `inside`) is the positive side.
pub fn marqueePlane(
    cam: model_paint.Camera,
    a: [2]f32,
    b: [2]f32,
    inside: [2]f32,
) ?struct { normal: [3]f32, offset: f32 } {
    const ray_a = model_paint.cameraRay(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, a[0], a[1]);
    const ray_b = model_paint.cameraRay(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, b[0], b[1]);
    var normal = z3d.vcross(ray_a.d, ray_b.d);
    const length = @sqrt(z3d.vdot(normal, normal));
    if (length <= 1e-9) return null;
    normal = z3d.vmul(normal, 1.0 / length);
    const ray_inside = model_paint.cameraRay(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, inside[0], inside[1]);
    if (z3d.vdot(normal, ray_inside.d) < 0) normal = z3d.vmul(normal, -1);
    return .{ .normal = normal, .offset = z3d.vdot(normal, cam.eye) };
}

/// One-shot verb: cut the authored face under the marquee centre by the marquee's
/// four projected edge planes and select the inside cells. One journal entry
/// ("marquee cut"); every refusal names itself in the topo-refusal slot.
pub fn meshTopoMarqueeCut(x0_raw: f32, y0_raw: f32, x1_raw: f32, y1_raw: f32) bool {
    z3d.g_topo_refusal = "";
    if (!model_paint.hasTarget()) {
        z3d.topoRefuse("no model is mounted for editing");
        return false;
    }
    if (z3d.meshLcActive()) {
        z3d.topoRefuse("a topology popup session is open — close it before cutting");
        return false;
    }
    if (mesh_edit.mode() != .face) {
        z3d.topoRefuse("marquee cut works in FACE select mode");
        return false;
    }
    const x0 = @min(x0_raw, x1_raw);
    const x1 = @max(x0_raw, x1_raw);
    const y0 = @min(y0_raw, y1_raw);
    const y1 = @max(y0_raw, y1_raw);
    if (x1 - x0 < 3 or y1 - y0 < 3) {
        z3d.topoRefuse("the marquee is too small to cut with — drag a real rectangle");
        return false;
    }
    const verts = z3d.g_edit_verts orelse {
        z3d.topoRefuse("no editable mesh is resident");
        return false;
    };
    const tri_count = z3d.g_edit_count / 3;
    if (tri_count == 0) {
        z3d.topoRefuse("the mesh has no triangles");
        return false;
    }
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    const lx0 = z3d.vpLocalX(x0);
    const lx1 = z3d.vpLocalX(x1);
    const ly0 = z3d.vpLocalY(y0);
    const ly1 = z3d.vpLocalY(y1);
    const center: [2]f32 = .{ (lx0 + lx1) * 0.5, (ly0 + ly1) * 0.5 };
    const seed_pick = model_paint.pick(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, center[0], center[1]);
    if (seed_pick < 0) {
        z3d.topoRefuse("the marquee centre must land on the face to cut — sweep the rectangle over one face");
        return false;
    }
    const seed_tri: u32 = @intCast(seed_pick);
    if (!mesh_edit.faceInScopePub(seed_tri)) {
        z3d.topoRefuse("the face under the marquee centre is outside the focused part's scope");
        return false;
    }

    // Capture the indexed base — the same boundary every cut session trusts.
    var groups: ?[]u32 = null;
    defer if (groups) |g| std.heap.c_allocator.free(g);
    if (model_source.faceGroupOf(0) != model_source.NO_FACE_GROUP) {
        const g = std.heap.c_allocator.alloc(u32, tri_count) catch return false;
        var i: u32 = 0;
        while (i < tri_count) : (i += 1) g[i] = model_source.faceGroupOf(i);
        groups = g;
    }
    const base_colors = z3d.collectCurrentFaceColors() orelse {
        z3d.topoRefuse("per-face colour capture failed");
        return false;
    };
    defer std.heap.c_allocator.free(base_colors);
    const base_face_part = z3d.capturePartOfFaces();
    defer if (base_face_part) |p| std.heap.c_allocator.free(p);
    const part_count = z3d.hostPartCount();
    const groups_arg: ?[]const u32 = if (groups) |g| g else null;
    const parts_arg: ?[]const u32 = if (base_face_part) |p| p else null;
    var cut_mesh = z3d.cloneIndexedEditMeshOrImport(verts, tri_count, groups_arg, parts_arg, model_source.faceMaterials()) orelse {
        z3d.topoRefuse("the resident mesh could not be indexed for cutting");
        return false;
    };
    defer cut_mesh.deinit();

    // The authored face under the marquee centre is the cut target; every piece a
    // plane splits off joins the family so the next plane cuts the pieces too.
    var family = std.ArrayListUnmanaged(u32).empty;
    defer family.deinit(std.heap.c_allocator);
    seed: for (cut_mesh.faces.items) |*face| {
        if (!face.alive) continue;
        for (face.source_triangles.items) |tri| {
            if (tri == seed_tri) {
                family.append(std.heap.c_allocator, face.id) catch return false;
                break :seed;
            }
        }
    }
    if (family.items.len == 0) {
        z3d.topoRefuse("the face under the marquee centre could not be found in the indexed mesh");
        return false;
    }

    const edge_pairs = [4][2][2]f32{
        .{ .{ lx0, ly0 }, .{ lx0, ly1 } }, // left
        .{ .{ lx1, ly0 }, .{ lx1, ly1 } }, // right
        .{ .{ lx0, ly0 }, .{ lx1, ly0 } }, // top
        .{ .{ lx0, ly1 }, .{ lx1, ly1 } }, // bottom
    };
    var changed: u32 = 0;
    for (edge_pairs) |pair| {
        const plane = z3d.marqueePlane(cam, pair[0], pair[1], center) orelse continue;
        var minted = std.AutoHashMapUnmanaged(u64, u32).empty;
        defer minted.deinit(std.heap.c_allocator);
        changed += cut_mesh.cutFamilyByPlane(&family, plane.normal, plane.offset, &minted) catch {
            z3d.topoRefuse("the marquee cut ran out of memory mid-plane and left the resident mesh untouched");
            return false;
        };
    }
    if (changed == 0) {
        z3d.topoRefuse("no marquee edge crosses the target face — drag the rectangle so it overlaps the face's interior");
        return false;
    }

    var lowered = cut_mesh.lower() catch {
        z3d.topoRefuse("the cut result could not be lowered for rendering");
        return false;
    };
    defer lowered.deinit();
    const colors = std.heap.c_allocator.alloc(u8, @as(usize, lowered.tri_count) * 4) catch return false;
    defer std.heap.c_allocator.free(colors);
    if (!mesh_edit.inheritFaceRgba(base_colors, lowered.source_triangles, colors)) {
        z3d.topoRefuse("the cut pieces could not inherit their face colours");
        return false;
    }

    var snap = z3d.journalSnapshotCurrent("marquee cut");
    const install_groups: ?[]const u32 = if (groups != null) lowered.groups else null;
    if (!z3d.lcInstallLowered(
        lowered.positions,
        lowered.uvs,
        lowered.tri_count,
        install_groups,
        lowered.materials,
        lowered.semantic_regions,
        lowered.semantic_instances,
        colors,
        z3d.flattenedLogicalRows(lowered.triangle_vertices),
        @intCast(cut_mesh.vertices.items.len),
    )) {
        z3d.journalDiscard(&snap);
        z3d.topoRefuse("the cut result was refused by the resident install");
        return false;
    }
    z3d.journalCommit(&snap);
    if (part_count > 0) z3d.renormalizePartRanges(lowered.parts, part_count);
    z3d.adoptIndexedEditMesh(&cut_mesh, &lowered);

    // The sweep's point: the cells INSIDE the rectangle come back selected, ready
    // to delete (the cutout), extrude, or paint.
    const inside_mask: ?[]bool = std.heap.c_allocator.alloc(bool, lowered.tri_count) catch null;
    if (inside_mask) |mask_buf| {
        defer std.heap.c_allocator.free(mask_buf);
        @memset(mask_buf, false);
        var tri: u32 = 0;
        while (tri < lowered.tri_count) : (tri += 1) {
            var in_family = false;
            for (family.items) |face_id| in_family = in_family or lowered.face_ids[tri] == face_id;
            if (!in_family) continue;
            const b = @as(usize, tri) * 9;
            const centroid: [3]f32 = .{
                (lowered.positions[b + 0] + lowered.positions[b + 3] + lowered.positions[b + 6]) / 3.0,
                (lowered.positions[b + 1] + lowered.positions[b + 4] + lowered.positions[b + 7]) / 3.0,
                (lowered.positions[b + 2] + lowered.positions[b + 5] + lowered.positions[b + 8]) / 3.0,
            };
            const sp = model_paint.project(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, centroid) orelse continue;
            if (sp[0] >= lx0 and sp[0] <= lx1 and sp[1] >= ly0 and sp[1] <= ly1) mask_buf[tri] = true;
        }
        _ = mesh_edit.selectFacesByTriangleMask(mask_buf);
    }
    return true;
}
